mapper.update:
UPDATE ai_clipping
SET
    title = #{title},
    content = #{content}
WHERE seq = #{seq}

UPDATE ai_clipping
SET del_yn = 'Y'
WHERE seq = #{seq}

UPDATE ai_clipping
SET view_cnt = view_cnt + 1
WHERE seq = #{seq}

UPDATE ai_clipping
SET share_cnt = share_cnt + 1
WHERE seq = #{seq}

UPDATE ai_clipping
SET
    send_success_cnt = send_success_cnt + #{sendSuccessCnt},
    send_fail_cnt = send_fail_cnt + #{sendFailCnt}
WHERE seq = #{seq}

mapper.select:
SELECT COUNT(*)
FROM ai_clipping_keyword
WHERE keyword = #{keyword}
